"""Render rows as a GitHub markdown table."""


def _cell(text):
    """Strip whitespace and escape pipes so the cell cannot break the table."""
    return text.strip().replace("|", "\\|")


def _line(cells):
    return "| " + " | ".join(cells) + " |"


def to_markdown(rows):
    """Rows is a list of lists of strings; the first row is the header."""
    if not rows:
        raise ValueError("no rows")
    header = [_cell(c) for c in rows[0]]
    if not header:
        raise ValueError("empty header")
    lines = [_line(header), _line(["---"] * len(header))]
    for n, row in enumerate(rows[1:], start=2):
        if len(row) != len(header):
            raise ValueError(f"row {n} has {len(row)} cells, expected {len(header)}")
        lines.append(_line([_cell(c) for c in row]))
    return "\n".join(lines)
